-- ═══════════════════════════════════════════════════════════════
-- b🌶te — seed content catalog
-- Idempotent: safe to run repeatedly (upserts by id).
-- ═══════════════════════════════════════════════════════════════

-- ─────────────────────────────────────────────
-- RECIPES
-- ─────────────────────────────────────────────
on conflict (id) do update set
  title = excluded.title, creator = excluded.creator, time_min = excluded.time_min,
  difficulty = excluded.difficulty, serves = excluded.serves, heat_level = excluded.heat_level,
  saved_count = excluded.saved_count, hearts_count = excluded.hearts_count, comments_count = excluded.comments_count,
  emoji = excluded.emoji, image_url = excluded.image_url, cuisine = excluded.cuisine,
  gradient = excluded.gradient, tags = excluded.tags;

-- ─────────────────────────────────────────────
-- DRINKS
-- ─────────────────────────────────────────────
on conflict (id) do update set
  title = excluded.title, creator = excluded.creator, time_min = excluded.time_min,
  difficulty = excluded.difficulty, serves = excluded.serves, heat_level = excluded.heat_level,
  saved_count = excluded.saved_count, hearts_count = excluded.hearts_count, comments_count = excluded.comments_count,
  emoji = excluded.emoji, image_url = excluded.image_url, cuisine = excluded.cuisine,
  gradient = excluded.gradient, tags = excluded.tags;

-- ─────────────────────────────────────────────
-- PLACES
-- ─────────────────────────────────────────────
on conflict (id) do update set
  title = excluded.title, creator = excluded.creator, price_level = excluded.price_level,
  cuisine = excluded.cuisine, saved_count = excluded.saved_count, hearts_count = excluded.hearts_count,
  comments_count = excluded.comments_count, emoji = excluded.emoji, image_url = excluded.image_url,
  gradient = excluded.gradient, address = excluded.address, phone = excluded.phone,
  rating = excluded.rating, review_count = excluded.review_count, hours = excluded.hours,
  status = excluded.status, distance = excluded.distance, photos = excluded.photos,
  tags = excluded.tags, menu_highlights = excluded.menu_highlights;
